<?php
declare(strict_types=1);
if(!defined('CMS_ENTRY'))exit;
function icon(string $name):string{return ['spark'=>'✳','grid'=>'▦','heart'=>'♡','arrow'=>'↗','check'=>'✓','star'=>'☆'][$name]??'✳';}
function inline_text(string $text):string{$parts=preg_split('~(`[^`\n]+`|\*\*[^*\n]+\*\*|\*[^*\n]+\*|\[[^\]\n]+\]\([^\s)]+\))~u',$text,-1,PREG_SPLIT_DELIM_CAPTURE);$out='';foreach($parts as $t){if(preg_match('/^`([^`]+)`$/s',$t,$m))$out.='<code>'.e($m[1]).'</code>';elseif(preg_match('/^\*\*([^*]+)\*\*$/s',$t,$m))$out.='<strong>'.e($m[1]).'</strong>';elseif(preg_match('/^\*([^*]+)\*$/s',$t,$m))$out.='<em>'.e($m[1]).'</em>';elseif(preg_match('~^\[([^\]]+)\]\(([^\s)]+)\)$~s',$t,$m)){$url=safe_url($m[2]);$out.=$url?'<a href="'.e(local_url($url)).'">'.e($m[1]).'</a>':e($m[1]);}else $out.=e($t);}return $out;}
function rich(mixed $source):string{$lines=explode("\n",str_replace("\r",'',txt($source,20000)));$html='';$p=[];$list=[];$listType='';$flush=function()use(&$html,&$p,&$list,&$listType){if($p){$html.='<p>'.implode('<br>',array_map('inline_text',$p)).'</p>';$p=[];}if($list){$html.='<'.$listType.'><li>'.implode('</li><li>',array_map('inline_text',$list)).'</li></'.$listType.'>';$list=[];$listType='';}};
 $cells=fn($s)=>array_map('trim',explode('|',trim(trim($s),'|')));
 for($i=0;$i<count($lines);$i++){$line=$lines[$i];if(trim($line)===''){$flush();continue;}if(str_contains($line,'|')&&isset($lines[$i+1])&&preg_match('/^\s*\|?\s*:?-{3,}/',$lines[$i+1])){$flush();$head=$cells($line);$i++;$html.='<div class="rich-table"><table><thead><tr>';foreach($head as $c)$html.='<th scope="col">'.inline_text($c).'</th>';$html.='</tr></thead><tbody>';while(isset($lines[$i+1])&&str_contains($lines[$i+1],'|')){$row=$cells($lines[++$i]);$html.='<tr>';foreach($head as $j=>$c)$html.='<td>'.inline_text($row[$j]??'').'</td>';$html.='</tr>';}$html.='</tbody></table></div>';continue;}if(preg_match('/^\s*(-|\d+\.)\s+(.+)$/',$line,$m)){$type=$m[1]==='-'?'ul':'ol';if($p||($listType&&$listType!==$type))$flush();$listType=$type;$list[]=$m[2];continue;}$flush();if(preg_match('/^(#{2,4})\s+(.+)$/',$line,$m))$html.='<h'.strlen($m[1]).'>'.inline_text($m[2]).'</h'.strlen($m[1]).'>';elseif(str_starts_with($line,'> '))$html.='<blockquote>'.inline_text(substr($line,2)).'</blockquote>';else $p[]=$line;}$flush();return $html;}
function target_url(string $id,array $context):string{foreach($context['pages'] as $p)if($p['id']===$id&&($context['preview']||$p['status']==='published'))return $context['routes'][$id]??($context['preview']?local_url('/preview/'.$id):local_url(page_path($p)));return '';}
function section_link(array $s,array $context):string{return !empty($s['linkPage'])?target_url($s['linkPage'],$context):local_url(safe_url($s['link']??''));}
function render_nav(array $items,array $site,array $context,bool $footer=false,bool $inMega=false,int $level=0):string{$html='';foreach($items as $item){$href='';if(!empty($item['page']))$href=target_url($item['page'],$context);elseif(!empty($item['category'])){foreach($context['categories'] as $c)if($c['id']===$item['category'])$href=local_url('/category/'.$c['slug'].'/');}else $href=local_url(safe_url($item['url']??''));$children=$item['children']??[];$preference=($item['layout']??'auto')!=='auto'?$item['layout']:($site['menuStyle']??'auto');$nested=(bool)array_filter($children,fn($c)=>!empty($c['children']));$mega=!$footer&&$level===0&&$children&&($preference==='mega'||$preference==='auto'&&$nested);$label=(!empty($item['icon'])?'<span class="nav-icon" aria-hidden="true">'.icon($item['icon']).'</span>':'').e($item['label']);$rel=trim((!empty($item['newTab'])?'noopener ':'').(!empty($item['nofollow'])?'nofollow':''));$anchor=fn($text,$overview=false)=>'<a href="'.e($href).'"'.(!empty($item['newTab'])?' target="_blank"':'').($rel?' rel="'.$rel.'"':'').(!empty($item['highlight'])&&!$overview?' class="nav-highlight"':'').'>'.$text.(!empty($item['description'])&&!$overview?'<small>'.e($item['description']).'</small>':'').'</a>';
 if(!$children&&(!$href&&(!empty($item['page'])||!empty($item['category']))))continue;
 if(!$children){$html.='<li class="nav-item">'.($href?$anchor($label):'<span class="nav-heading">'.$label.'</span>').'</li>';continue;}
 $child=render_nav($children,$site,$context,$footer,$mega||$inMega,$level+1);if(!$child)continue;$column=$inMega&&$level===1;$classes='nav-group level-'.$level.($mega?' nav-mega':' nav-dropdown').($column?' nav-column':'');$html.='<li class="nav-item"><details class="'.$classes.'"'.($column?' open data-mega-column':'').' style="--menu-columns:'.max(2,min(4,(int)($item['columns']??3))).'"><summary>'.$label.'</summary><ul>'.($href?'<li class="nav-overview">'.$anchor('Explore '.e($item['label']),true).'</li>':'').$child.'</ul></details></li>';}
 return $html;}
function render_pricing(array $s,array $ctx):string{$p=$s['pricing']??['plans'=>[],'layout'=>'cards','skin'=>'clean','currency'=>'','note'=>''];$price=fn($plan)=>'<div class="plan-price">'.(!empty($plan['previousPrice'])?'<s><span class="sr-only">Previous price </span>'.e($p['currency'].$plan['previousPrice']).'</s>':'').'<strong>'.e(!empty($plan['price'])?$p['currency'].$plan['price']:'Contact us').'</strong>'.(!empty($plan['period'])?'<span>'.e($plan['period']).'</span>':'').'</div>';$badge=fn($plan)=>!empty($plan['badge'])?'<span class="plan-badge">'.e($plan['badge']).'</span>':'';$description=fn($plan)=>!empty($plan['description'])?'<p class="plan-description">'.e($plan['description']).'</p>':'';$button=function($plan)use($ctx){$link=section_link($plan,$ctx);return !empty($plan['button'])&&$link?'<a class="button pricing-button" href="'.e($link).'">'.e($plan['button']).' <span aria-hidden="true">↗</span></a>':'';};$html='';
 if($p['layout']==='comparison'){$html.='<div class="pricing-table-scroll" role="region" aria-label="'.e($s['title']??'Compare plans').'" tabindex="0"><table class="pricing-comparison"><caption>'.e($s['title']??'Compare plans').'</caption><thead><tr><th scope="col">Plan details</th>';$labels=[];foreach($p['plans'] as $plan){foreach($plan['features'] as $f)$labels[$f['label']]=true;$html.='<th scope="col" class="'.(!empty($plan['featured'])?'plan-featured':'').'">'.$badge($plan).'<h3>'.e($plan['name']).'</h3>'.$description($plan).$price($plan).$button($plan).'</th>';}$html.='</tr></thead><tbody>';foreach(array_keys($labels) as $label){$html.='<tr><th scope="row">'.e($label).'</th>';foreach($p['plans'] as $plan){$features=array_column($plan['features'],'value','label');$html.='<td class="'.(!empty($plan['featured'])?'plan-featured':'').'">'.(array_key_exists($label,$features)?e($features[$label]):'<span aria-label="Not specified">—</span>').'</td>';}$html.='</tr>';}$html.='</tbody></table></div>';
 }else{$html.='<div class="pricing-plans">';foreach($p['plans'] as $plan){$html.='<article class="pricing-plan '.(!empty($plan['featured'])?'plan-featured':'').'"><div class="plan-heading">'.$badge($plan).'<h3>'.e($plan['name']).'</h3>'.$description($plan).'</div><div class="plan-offer">'.$price($plan).$button($plan).'</div><dl class="plan-features">';foreach($plan['features'] as $f)$html.='<div><dt>'.e($f['label']).'</dt><dd>'.e($f['value']).'</dd></div>';$html.='</dl></article>';}$html.='</div>';}
 return '<div class="pricing pricing-'.e($p['layout']).' pricing-skin-'.e($p['skin']).'">'.$html.(!empty($p['note'])?'<p class="pricing-note">'.e($p['note']).'</p>':'').'</div>';}
function render_section(array $s,array $site,array $ctx):string{
 $title=!empty($s['title'])?'<h2>'.nl2br(e($s['title'])).'</h2>':'';$intro=(!empty($s['eyebrow'])?'<div class="eyebrow">'.e($s['eyebrow']).'</div>':'').$title.rich($s['text']??'');$link=section_link($s,$ctx);$button=!empty($s['button'])&&$link?'<a class="button" href="'.e($link).'">'.e($s['button']).' <span aria-hidden="true">↗</span></a>':'';$image=!empty($s['image'])?'<img src="'.e(local_url($s['image'])).'" alt="'.e($s['alt']??'').'" '.($s['type']==='hero'?'fetchpriority="high"':'loading="lazy"').' decoding="async" width="1536" height="1024">':'';$body='';
 switch($s['type']){
 case 'hero':$body='<div class="hero-copy">'.(!empty($s['eyebrow'])?'<div class="eyebrow"><span class="dot"></span>'.e($s['eyebrow']).'</div>':'').'<h1>'.nl2br(e($s['title']??'')).'</h1>'.rich($s['text']??'').$button.'</div>'.($image?'<div class="hero-image">'.$image.'</div>':'<div class="hero-art" aria-hidden="true"><div></div><div></div><span>Ideas into possibilities.</span></div>');break;
 case 'pricing':$body=$intro.render_pricing($s,$ctx);break;
 case 'text':$body='<div class="text-layout">'.(!empty($s['eyebrow'])?'<div class="eyebrow">'.e($s['eyebrow']).'</div>':'').'<div>'.$title.rich($s['text']??'').'</div></div>';break;
 case 'image':$body=$image.'<div class="image-caption">'.$intro.'</div>';break;
 case 'features':case 'testimonials':$body='<div class="section-heading">'.$intro.'</div><div class="cards">';foreach($s['items']??[] as $i)$body.='<article class="card">'.($s['type']==='features'?'<span class="feature-icon" aria-hidden="true">'.icon($i['icon']??'spark').'</span>':'<span class="quote" aria-hidden="true">“</span>').'<h3>'.e($i['title']).'</h3>'.rich($i['text']).'</article>';$body.='</div>';break;
 case 'gallery':$body=$intro.'<div class="gallery">';foreach($s['items']??[] as $i)$body.='<figure>'.(!empty($i['image'])?'<img src="'.e(local_url($i['image'])).'" alt="'.e($i['alt']??'').'" loading="lazy" width="900" height="600">':'').'<figcaption><h3>'.e($i['title']).'</h3>'.rich($i['text']).'</figcaption></figure>';$body.='</div>';break;
 case 'timeline':$body=$intro.'<ol class="timeline">';foreach($s['items']??[] as $i)$body.='<li><h3>'.e($i['title']).'</h3>'.rich($i['text']).'</li>';$body.='</ol>';break;
 case 'faq':$body=$intro.'<div class="faq">';foreach($s['items']??[] as $i)$body.='<details><summary>'.e($i['title']).'</summary>'.rich($i['text']).'</details>';$body.='</div>';break;
 case 'cta':$body=$intro.$button;break;
 case 'collection':$selected=$s['selected']??array_values(array_filter($ctx['pages'],fn($p)=>$p['status']==='published'&&($p['kind']??'page')===($s['collectionKind']??'post')&&(empty($s['linkCategory'])||in_array($s['linkCategory'],$p['categories']??[],true))));usort($selected,fn($a,$b)=>strcmp($b['date']??'',$a['date']??''));$body=$intro.'<div class="cards collection-cards">';foreach(array_slice($selected,0,$s['itemLimit']??6) as $p)$body.='<article class="card">'.(!empty($p['seo']['image'])?'<img src="'.e(local_url($p['seo']['image'])).'" alt="" loading="lazy" width="640" height="400">':'').'<h3><a href="'.e(target_url($p['id'],$ctx)).'">'.e($p['title']).'</a></h3>'.(!empty($p['date'])?'<small>'.e($p['date']).'</small>':'').rich($p['excerpt']??'').'</article>';$body.='</div>';break;
 case 'links':$body=$intro.'<div class="link-directory">';foreach($ctx['links'] as $i){if(!empty($s['linkCategory'])&&($i['category']??'')!==$s['linkCategory'])continue;$href=!empty($i['page'])?target_url($i['page'],$ctx):local_url(safe_url($i['url']??''));if(!$href)continue;$rel=trim((!empty($i['newTab'])?'noopener ':'').(!empty($i['nofollow'])?'nofollow ':'').(!empty($i['sponsored'])?'sponsored':''));$body.='<article class="directory-link"><a href="'.e($href).'"'.(!empty($i['newTab'])?' target="_blank"':'').($rel?' rel="'.$rel.'"':'').'>'.e($i['label']).' ↗</a>'.rich($i['description']??'').'</article>';}$body.='</div>';break;
 case 'search':$body='<form class="site-search" role="search"><label for="site-search">Search this website</label><input id="site-search" type="search" name="q" placeholder="Type a word or phrase…"><button class="button" type="submit">Search ↗</button></form><p id="search-status" role="status"></p><div id="search-results" class="link-directory"></div>';break;
 case 'contact':$body='<div class="contact-grid"><div>'.$intro.(!empty($site['email'])?'<p><a href="mailto:'.e($site['email']).'">'.e($site['email']).'</a></p>':'').(!empty($site['phone'])?'<p>'.e($site['phone']).'</p>':'').rich($site['address']??'').'</div><form method="post" action="'.e(!empty($site['formEndpoint'])?local_url($site['formEndpoint']):local_url('/api/contact')).'" class="contact-form"><label>Your name<input name="name" required maxlength="120" autocomplete="name"></label><label>Email address<input type="email" name="email" required maxlength="254" autocomplete="email"></label><label>How can we help?<textarea name="message" required minlength="10" maxlength="10000" rows="5"></textarea></label><label class="honeypot" aria-hidden="true">Leave empty<input name="website" tabindex="-1" autocomplete="off"></label><p class="form-note">Your details will be used to respond to your enquiry.</p><button class="button" type="submit">Send message ↗</button></form></div>';break;
 }
 return '<section'.(!empty($s['id'])?' id="section-'.e($s['id']).'"':'').' class="section section-'.e($s['type']).'"><div class="container">'.$body.'</div></section>';
}
function accent_ink(string $hex):string{$channels=[];foreach(str_split(substr($hex,1),2) as $c){$v=hexdec($c)/255;$channels[]=$v<=.04045?$v/12.92:(($v+.055)/1.055)**2.4;}$l=$channels[0]*.2126+$channels[1]*.7152+$channels[2]*.0722;return 1.05/($l+.05)>=4.5?'#ffffff':'#000000';}
function render_page(array $page,array $site,array $pages,array $categories=[],array $links=[],bool $preview=false,array $routes=[]):string{
 $ctx=['pages'=>$pages,'categories'=>$categories,'links'=>$links,'preview'=>$preview,'routes'=>$routes];if(($site['bundledArtwork']??true)!==false){$subject=$page['starterId']??'';if(!$subject)$subject=catalog()['themeArt'][$site['theme']]??'';if($subject)foreach($page['sections'] as &$s)if($s['type']==='hero'&&empty($s['image'])){$s['image']='/assets/starter-images/'.$subject.'.jpg';$s['alt']=array_values(array_filter(catalog()['starters'],fn($x)=>$x['id']===$subject))[0]['alt']??'Illustrative sample artwork';}unset($s);}
 $home='';foreach($pages as $p)if($p['slug']===''){$home=target_url($p['id'],$ctx);break;}$home=$home?:local_url('/');$canonical=rtrim($site['url'],'/').page_path($page);$title=$page['seo']['title']??'';$title=$title?:($page['slug']?$page['title'].' — '.$site['name']:$site['name'].' — '.$site['tagline']);$desc=$page['seo']['description']??'';$desc=$desc?:$site['description'];$social=$page['seo']['image']??'';$social=$social?:($site['socialImage']??'');
 $entity=['@context'=>'https://schema.org','@type'=>$site['entity'],'name'=>$site['name'],'url'=>$site['url'],'description'=>$site['description'],'sameAs'=>array_column($site['social'],'url')];if(($page['kind']??'')==='post')$entity=[$entity,['@context'=>'https://schema.org','@type'=>'BlogPosting','headline'=>$page['title'],'datePublished'=>$page['date']??'','author'=>['@type'=>'Person','name'=>$page['author']?:$site['name']],'mainEntityOfPage'=>$canonical]];
 $html='<!doctype html><html data-base="'.e(base_path()).'" lang="'.e($site['language']).'" dir="'.$site['direction'].'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).'</title><meta name="description" content="'.e($desc).'"><link rel="canonical" href="'.e($canonical).'">'.($preview||!empty($page['seo']['noindex'])?'<meta name="robots" content="noindex,nofollow">':'').'<meta property="og:type" content="'.(($page['kind']??'')==='post'?'article':'website').'"><meta property="og:title" content="'.e($title).'"><meta property="og:description" content="'.e($desc).'"><meta property="og:url" content="'.e($canonical).'"><meta name="twitter:card" content="'.($social?'summary_large_image':'summary').'">'.($social?'<meta property="og:image" content="'.e(rtrim($site['url'],'/').$social).'">':'').(!empty($site['favicon'])?'<link rel="icon" href="'.e(local_url($site['favicon'])).'">':'').'<link rel="stylesheet" href="'.e(local_url('/assets/site.css')).'"><link rel="stylesheet" href="'.e(local_url('/assets/templates.css')).'"><style>:root{--accent:'.$site['accent'].';--accent-ink:'.accent_ink($site['accent']).'}</style><script type="application/ld+json">'.json_encode($entity,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script><script src="'.e(local_url('/assets/site.js')).'" defer></script></head><body class="theme-'.$site['theme'].' font-'.$site['font'].' mega-style-'.$site['megaStyle'].' subject-'.e(($page['starterId']??'')?:'custom').' layout-'.e(($page['starterLayout']??'')?:$site['starterLayout']).'"><a class="skip" href="#main">Skip to content</a>'.($preview?'<div class="preview-banner">PRIVATE PREVIEW · Unpublished changes</div>':'');
 $html.='<header class="site-header header-'.$site['headerStyle'].(!empty($site['stickyHeader'])?' is-sticky':'').(($site['menuAlign']??'')==='center'?' nav-centered':'').'">';if($site['headerStyle']==='utility')$html.='<div class="header-utility"><div class="container"><span>'.e($site['tagline']).'</span><div>'.(!empty($site['email'])?'<a href="mailto:'.e($site['email']).'">'.e($site['email']).'</a>':'').'<span>'.e($site['phone']??'').'</span></div></div></div>';
 $html.='<div class="container header-inner"><a class="brand" href="'.e($home).'">'.(!empty($site['logo'])?'<img src="'.e(local_url($site['logo'])).'" width="40" height="40" alt="">':'<span class="brand-symbol" aria-hidden="true">✳</span>').e($site['name']).'</a><nav aria-label="Main navigation"><button class="nav-toggle" aria-expanded="false" aria-controls="main-menu">Menu <span>☰</span></button><ul id="main-menu" class="main-menu">'.render_nav($site['menus'],$site,$ctx).(!empty($site['showSearch'])?'<li class="nav-item nav-search"><a href="'.e(local_url('/search/')).'">Search ⌕</a></li>':'').'</ul></nav></div></header><main id="main">';foreach($page['sections'] as $s)if(empty($s['hidden']))$html.=render_section($s,$site,$ctx);
 $html.='</main><footer id="site-footer" class="site-footer footer-'.$site['footerStyle'].'"><div class="container"><div class="footer-top"><a class="brand" href="'.e($home).'">'.e($site['name']).'</a><p>'.e($site['footer']).'</p><ul>'.render_nav($site['footerMenus'],$site,$ctx,true).'</ul></div><div class="footer-bottom"><span>© '.gmdate('Y').' '.e($site['copyright']?:$site['name']).'</span><div>';foreach($site['social'] as $s)$html.='<a href="'.e(local_url($s['url'])).'" rel="me">'.e($s['label']).' ↗</a>';$html.='</div></div></div></footer></body></html>';return $html;
}
